using System;using System.Collections.Generic;using System.IO;using System.Globalization;using System.Threading;using D=OsuLegacy.Difficulty;
namespace OsuLegacy {
 public static class LocalDifficulty {
  public const string Version="lazer-20260706-mania20241007-adapter1";
  public static double Calculate(string path,int mode,ModSettings settings,Action checkpoint){D.Engine.Checkpoint=checkpoint;Beatmap.LoadCheckpoint=checkpoint;try{if(checkpoint!=null)checkpoint();Beatmap map=Beatmap.Load(path,true,true);if(map.Mode!=mode && map.Mode!=0)throw new NotSupportedException("This beatmap cannot convert to the selected ruleset");if(mode==1&&map.Mode==0)map.ConvertToTaiko();if(mode==2)map.Mode=2;if(mode==3 && map.Mode==0)ManiaConversionAdapter.Prepare(map,true);if(settings!=null)settings.Apply(map);double rate=settings==null?1:settings.Rate;double result;
   if(mode==0)result=Standard(map,rate,settings);else if(mode==1)result=Taiko(map,rate,settings);else if(mode==2)result=Catch(map,rate);else result=Mania(map,rate);
   if(double.IsNaN(result)||double.IsInfinity(result)||result<0)throw new FormatException("Difficulty calculation produced an invalid result");return result;
  }finally{D.Engine.Checkpoint=null;Beatmap.LoadCheckpoint=null;}}
  private static D.Vector2 Vector(double x,double y){return new D.Vector2((float)x,(float)y);}
  private static double Standard(Beatmap map,double rate,ModSettings settings){var hits=new List<D.Osu.OsuHitObject>(map.Objects.Count);double radius=(54.4-4.48*map.CS)*1.00041,preempt=map.AR<=5?1800-120*map.AR:1200-150*(map.AR-5);int processed=0;foreach(Circle source in map.Objects){if((processed++&31)==0)D.Engine.Check();D.Osu.OsuHitObject hit=source.Kind==ObjectKind.Slider?(D.Osu.OsuHitObject)new D.Osu.Slider():source.Kind==ObjectKind.Spinner?(D.Osu.OsuHitObject)new D.Osu.Spinner():new D.Osu.HitCircle();hit.StartTime=source.Time;hit.EndTime=source.EndTime;hit.Position=Vector(source.X,source.Y);hit.EndPosition=hit.Position;hit.Radius=radius;hit.TimePreempt=preempt;hit.TimeFadeIn=400*Math.Min(1,preempt/450);hit.HitWindows.Great=79.5-6*map.OD;if(settings!=null && settings.Has("HD") && !(hit is D.Osu.Slider))hit.TimeFadeIn=preempt*.4;
    var slider=hit as D.Osu.Slider;if(slider!=null){Circle captured=source;slider.RepeatCount=source.SpanCount-1;slider.Duration=source.Duration;slider.Path.Distance=source.Path.Length;slider.Path.PositionAt=delegate(double progress){PathPoint p=captured.Path.Position(progress);return Vector(p.X-captured.X,p.Y-captured.Y);};slider.EndPosition=slider.Position+slider.Path.PositionAt(source.SpanCount%2);slider.HeadCircle=new D.Osu.SliderHeadCircle{StartTime=source.Time,EndTime=source.Time,Position=hit.Position,Radius=radius};slider.NestedHitObjects.Add(slider.HeadCircle);
     foreach(SliderEvent e in source.Events){D.Osu.OsuHitObject nested=e.Tail?(D.Osu.OsuHitObject)new D.Osu.SliderTailCircle():e.Repeat?(D.Osu.OsuHitObject)new D.Osu.SliderRepeat():new D.Osu.SliderTick();PathPoint p=source.PositionAt(e.Time);nested.Position=Vector(p.X,p.Y);nested.StartTime=nested.EndTime=e.Time;nested.Radius=radius;slider.NestedHitObjects.Add(nested);if(e.Tail)slider.TailCircle=(D.Osu.SliderTailCircle)nested;}
    }hits.Add(hit);}
   var mods=new List<D.Mod>();if(settings!=null){if(settings.Has("HD"))mods.Add(new D.OsuModHidden());if(settings.Has("FL"))mods.Add(new D.OsuModFlashlight());if(settings.Has("RX"))mods.Add(new D.OsuModRelax());if(settings.Has("AP"))mods.Add(new D.OsuModAutopilot());}return D.Engine.Standard(hits,rate,mods.ToArray(),map.Version,map.StackLeniency);
  }
  private static double Mania(Beatmap map,double rate){var hits=new List<D.Mania.ManiaHitObject>(map.Objects.Count);foreach(Circle o in map.Objects)hits.Add(new D.Mania.ManiaHitObject{StartTime=o.Time,EndTime=o.EndTime,Column=o.Column});return D.Engine.ManiaRating(hits,map.ManiaColumns,rate);}
  private static double Catch(Beatmap map,double rate){var converted=new CatchSession(new Session(map,true),true);var hits=new List<D.Catch.PalpableCatchHitObject>();foreach(CatchObject o in converted.Objects)if(o.Kind==CatchKind.Fruit||o.Kind==CatchKind.Droplet)hits.Add(new D.Catch.PalpableCatchHitObject{StartTime=o.Time,EndTime=o.Time,EffectiveX=(float)o.X,HyperDash=o.HyperTarget>=0,DistanceToHyperDash=(float)Math.Max(0,o.HyperDistance)});float half=(float)converted.CatchWidth*.5f;half*=1-(Math.Max(0,(float)map.CS-5.5f)*.0625f);return D.Engine.CatchRating(hits,rate,half);}
  private static double Taiko(Beatmap map,double rate,ModSettings settings){var hits=new List<D.Taiko.TaikoHitObject>(map.Objects.Count);foreach(Circle o in map.Objects){D.Taiko.TaikoHitObject hit=o.Kind==ObjectKind.Spinner?(D.Taiko.TaikoHitObject)new D.Taiko.Swell():o.Kind==ObjectKind.Slider?(D.Taiko.TaikoHitObject)new D.Taiko.DrumRoll():new D.Taiko.Hit{IsRim=(o.HitSound&10)!=0,IsStrong=(o.HitSound&4)!=0};hit.StartTime=o.Time;hit.EndTime=o.EndTime;hits.Add(hit);}var points=map.ExportTiming();return D.Engine.TaikoRating(hits,rate,new D.Taiko.ControlPointInfo{BeatLengthAt=map.BeatLengthAt,ScrollSpeedAt=delegate(double t){double sv=1;foreach(double[] p in points){if(p[0]>t)break;sv=p[2]==1?1:p[1]<0?Math.Max(.1,Math.Min(10,-100/p[1])):1;}return sv;}},map.SliderMultiplier,map.TaikoConverted,settings!=null&&settings.Has("RX"));}
 }
 public sealed class DifficultyCache {
  private sealed class Entry {public string Path,Key,Fingerprint,Error;public int Mode;public ModSettings Settings;public double Stars=-1;public bool Finished;public long Checked;}
  private readonly object gate=new object();private readonly Dictionary<string,Entry> entries=new Dictionary<string,Entry>();private Entry pending,active;private bool running;private int revision;private readonly string directory;
  public Action WorkerStarted,WorkerCheckpoint;public int Calculations,Hits;public int Revision{get{lock(gate)return revision;}}
  public DifficultyCache(string documents){directory=Path.Combine(documents,"DifficultyCache");Directory.CreateDirectory(directory);}
  public static string SettingsKey(ModSettings s){return s==null?"None":s.Summary+"|"+s.Rate.ToString("R",CultureInfo.InvariantCulture)+"|"+s.CS+"|"+s.AR+"|"+s.OD+"|"+s.HP+"|"+(s.Has("RD")?s.Seed:0);}
  public double Request(string path,int mode,ModSettings settings){if(string.IsNullOrEmpty(path))return -1;string key=path+"\n"+mode+"\n"+SettingsKey(settings);lock(gate){Entry e;if(!entries.TryGetValue(key,out e)){if(entries.Count>=128)entries.Clear();entries[key]=e=new Entry{Path=path,Mode=mode,Settings=settings,Key=key};}if(e!=active && (e!=pending) && (!e.Finished || DateTime.UtcNow.Ticks-e.Checked>5*TimeSpan.TicksPerSecond)){pending=e;if(!running){running=true;new Thread(Loop){IsBackground=true}.Start();}}return e.Stars;}}
  private static string Hash(string value){using(var hash=System.Security.Cryptography.SHA1.Create()){byte[] data=hash.ComputeHash(System.Text.Encoding.UTF8.GetBytes(value));return BitConverter.ToString(data).Replace("-","").ToLowerInvariant();}}
  public void Invalidate(string path){lock(gate){foreach(var e in entries.Values)if(e.Path==path){e.Checked=0;e.Finished=false;e.Stars=-1;}revision++;}}
  private void Loop(){if(WorkerStarted!=null)WorkerStarted();while(true){Entry e;lock(gate){e=pending;pending=null;active=e;if(e==null){running=false;return;}}try{
    Action check=delegate{if(WorkerCheckpoint!=null)WorkerCheckpoint();lock(gate){if(pending!=null && pending!=e)throw new OperationCanceledException();}};check();var info=new FileInfo(e.Path);if(!info.Exists)throw new FileNotFoundException("Beatmap deleted",e.Path);string fingerprint=LocalDifficulty.Version+"|"+info.Length+"|"+info.LastWriteTimeUtc.Ticks;
    lock(gate){if(e.Finished && e.Fingerprint==fingerprint){e.Checked=DateTime.UtcNow.Ticks;continue;}e.Fingerprint=fingerprint;}
    string cache=Path.Combine(directory,Hash(e.Key)+".txt");double value=-1;bool cached=false;if(File.Exists(cache)){string[] fields=File.ReadAllLines(cache);cached=fields.Length==2&&fields[0]==fingerprint&&double.TryParse(fields[1],NumberStyles.Float,CultureInfo.InvariantCulture,out value)&&!double.IsNaN(value)&&!double.IsInfinity(value)&&value>=0;}
    if(!cached){value=LocalDifficulty.Calculate(e.Path,e.Mode,e.Settings,check);check();var after=new FileInfo(e.Path);if(after.Length!=info.Length||after.LastWriteTimeUtc.Ticks!=info.LastWriteTimeUtc.Ticks)throw new OperationCanceledException();string stage=cache+".part";File.WriteAllText(stage,fingerprint+"\n"+value.ToString("R",CultureInfo.InvariantCulture));if(File.Exists(cache))File.Delete(cache);File.Move(stage,cache);Calculations++;Console.WriteLine("OSU difficulty: mode {0}, {1:F2} stars",e.Mode,value);}else Hits++;
    lock(gate){if(e.Stars!=value)revision++;e.Stars=value;e.Fingerprint=fingerprint;e.Error=null;e.Finished=true;e.Checked=DateTime.UtcNow.Ticks;}
   }catch(OperationCanceledException){lock(gate){e.Finished=false;}}catch(Exception error){lock(gate){if(e.Stars!=-1)revision++;e.Stars=-1;e.Error=error.Message;e.Finished=true;e.Checked=DateTime.UtcNow.Ticks;}}finally{lock(gate)active=null;}}}
 }
}
